201:     // Conservative waiter-aware protection persists after a merged waiter
202:     // retires. No future reuse oracle is consumed by this policy.
203:     if (!m_features.tag_detach || !e.attached || e.reuse_seen ||
204:         !(e.required & ~e.ready)) return false;
205:     if (!m_port.tag_matches(e.tag, h, e.line))
206:       throw std::logic_error("tag reuse without detach handshake");
207:     m_port.tag_detach(e.tag, h); e.attached = false;
208:     ++stats.detached;
209:     return true;
210:   }
